const CACHE_NAME = 'arapy-beauty-pwa-v3';
const CORE_ASSETS = [
  './',
  './index.html',
  './manifest.webmanifest',
  './assets/splash-hero.jpg',
  './assets/studio-nails.jpg',
  './assets/inspo-black-gold.jpg',
  './assets/inspo-rose-french.jpg',
  './assets/hair-balayage.jpg',
  './assets/stylist-main.jpg',
  './assets/hair-cut.jpg',
  './assets/studio-lounge.jpg'
];

self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll(CORE_ASSETS).catch(() => {});
    })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys.map((key) => {
          if (key !== CACHE_NAME) {
            return caches.delete(key);
          }
          return null;
        })
      )
    )
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;
  if (event.request.url.includes('/api/')) return;

  event.respondWith(
    fetch(event.request)
      .then((response) => {
        if (response && response.status === 200 && response.type === 'basic') {
          const clone = response.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(event.request, clone));
        }
        return response;
      })
      .catch(() => caches.match(event.request))
  );
});
